#!/usr/bin/env python3
"""Human-readable interim report. Intentionally separates experiments from product QA."""
import argparse,html,json,hashlib
from datetime import datetime,timezone
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--output',required=True,type=Path)
p.add_argument('--worker-queue',type=Path);p.add_argument('--references',type=Path)
p.add_argument('--progress-json',type=Path)
a=p.parse_args()

def queue_snapshot(queue_file, references):
    queue=json.loads(queue_file.read_text());seen=set();passed=0;failed=0;unverified=0;duplicates=0;closed=0;parse_errors=0
    for file in sorted(queue_file.parent.glob('batch-*/report.json')):
        try: report=json.loads(file.read_text())
        except (OSError,json.JSONDecodeError):
            parse_errors+=1;continue
        if report.get('pass') is False or report.get('failure'):failed+=1
        for row in report.get('cases',[]):
            request=row.get('request',{});result=row.get('result',{});audit=row.get('rawAudit',{});carrier=row.get('carrier',{})
            key=(request.get('fixture'),request.get('algorithm'),json.dumps(request.get('config',{}),sort_keys=True))
            if row.get('pass') is False or row.get('failure'):
                failed+=1;continue
            raw=carrier.get('decodedSHA256');source=report.get('sourceHashes')
            valid=(row.get('pass') is True and request.get('fixedInitialWet') is True
                and row.get('fixedInitialWetVerified') is True and row.get('sameFixtureInput') is True
                and audit.get('pass') is True and source and audit.get('sourceHashes')==source
                and raw and audit.get('rawSHA')==raw and raw in result.get('hashes',[])
                and audit.get('inputSHA')==result.get('fixtureSHA')==request.get('expectedInputSHA')
                and audit.get('changedDryChannels')==0 and carrier.get('decodedBytes')==4194304)
            if not valid:
                unverified+=1;continue
            if key in seen:
                duplicates+=1;continue
            seen.add(key);passed+=1
            if report.get('pass') is True and report.get('sourceStable') is True and report.get('contextClosed') is True:closed+=1
    refs=0
    if references:
        rows=json.loads(references.read_text());ids=set()
        for row in rows:
            audit=row.get('rawAudit',{});sha=row.get('result',{}).get('fixtureSHA',{});image=row.get('variant',{}).get('imageSource')
            if (row.get('inputReferenceExact') is True and audit.get('pass') is True
                and row.get('rawSHA')==sha.get('rgba')==audit.get('rawSHA')
                and audit.get('inputSHA')==sha and audit.get('sourceHashes')==row.get('sourceHashes')
                and image and hashlib.sha256(Path(image).read_bytes()).hexdigest()==row.get('pngSHA')):ids.add(row['sceneId'])
        refs=len(ids)
    return dict(snapshotUTC=datetime.now(timezone.utc).isoformat(timespec='seconds'),startedAt=queue.get('startedAt'),
        plannedWorker=queue['planned'],excludedCapillary=queue['excluded'],auditedUniqueRows=passed,
        closedBatchRows=closed,failedRowsOrBatches=failed,unverifiedRows=unverified,duplicateRows=duplicates,
        updatingReportFiles=parse_errors,referencesVerified=refs,nativeComponentStatus='pending',complete=False)

body='''<h1>Исследование растекания: промежуточный отчёт</h1>
<p>Работа продолжается. Готового победителя по скорости и художественному качеству пока нет. Это проверка алгоритмов на отдельном стенде, а не завершённое тестирование Grafetto.</p>
<h2>Неподвижная исходная лужа — работа 18 октября</h2><p>Принято правило: краска перемещается только внутри исходной мокрой области. Опубликованные ниже ночные результаты ещё не приведены к этому правилу во всех алгоритмах. Их нельзя считать проверкой фиксированной границы.</p><p>CPU-прототип проверен: сухие исходные пиксели неизменны, тонкие мокрые линии шириной 1, 2 и 7 пикселей передают и смешивают цвет, через сухую полосу переноса нет. Один отдельный GPU-вариант проверен на Samsung: 10 сценариев по 3 повтора, сухие пиксели неизменны, тонкие лужи смешивают цвет, через сухие разделители переноса нет. В фиксированном порядке получены 233 мс для Mini-волны и 190 мс для листа 12; это не измерение выигрыша. Остальные алгоритмы ещё требуют отдельного переноса и пересчёта, вся матрица не готова.</p><h2>Что выяснилось</h2><table><thead><tr><th>Проблема простыми словами</th><th>Состояние</th></tr></thead><tbody>
<tr><td>Несколько прежних быстрых вариантов меняли фактуру и край, но почти не переносили краску по большой луже.</td><td>Подтверждено контрольными сценами. Добавлены модели с заметным переносом.</td></tr>
<tr><td>Новые варианты действительно смешивают раздельные цвета, но часть картинок выглядит как размытие, полосатые копии, клетчатое пятно или аэрозоль.</td><td>Не решено. Такие картинки не считаются художественно удачными.</td></tr>
<tr><td>Большинство первых экспериментов двигало краску только внутри исходной воды. Когда вода совпадает с мазком, его внешний контур почти не меняется.</td><td>Новая модель с продвижением воды проверена на Samsung. Плавная реконструкция убрала видимую клетку, но художественный выбор ещё не сделан.</td></tr>
<tr><td>Частицы проскакивают через углы диагональной сухой полосы в модели с неподвижной мокрой областью.</td><td>Исправлено и повторно проверено на Samsung: через диагональную и однопиксельную полосу переноса нет.</td></tr>
<tr><td>Первый вариант с частицами не компилировался в настоящем браузере.</td><td>Исправлено и повторно проверено на Samsung.</td></tr>
<tr><td>Первый счётчик переноса через однопиксельную полосу принимал соседний мокрый столбец за другую сторону.</td><td>Исправлено. Повторный расчёт подтвердил: пиксели модели совпадают, переноса через вертикальную полосу нет.</td></tr>
<tr><td>В новом варианте с общей водой штрих снаружи лужи расплывается сильнее, чем внутри неё.</td><td>В новой формуле исправлено на контрольном штрихе: внутри 26.6px, снаружи 10.9px. На широких настоящих мазках выход за контур небольшой, но исходная модель тоже почти не выходит за этот контур. Смешение и внутреннюю структуру проверяем отдельно; расширена проверка количества воды.</td></tr>
<tr><td>Очень слабый цвет частично теряется при округлении в 8-битную картинку.</td><td>У целочисленного варианта количество материала внутри расчёта сохраняется точно, но один слабый цветовой канал на выходе теряет около 41%. Исправлено безопасным распределённым округлением: на контрольной капле слабый канал сохраняется примерно на 99%, вода без пигмента не создаёт цвет. Это не полная проверка всех слабых цветов.</td></tr>
<tr><td>Даже один неподвижный пиксель включал клетчатое отображение на всём листе.</td><td>Исправлено локальным восстановлением: неподвижный пиксель больше не включает клетку на всём листе. На его собственной границе остаётся небольшая погрешность восстановления.</td></tr>
<tr><td>Вариант округления создавал цвет на пустой бумаге.</td><td>Найдено и воспроизведено отдельно: на Samsung остаток от деления на константу вычисляется неверно в 8180 из 16384 входов. Вариант с точным побайтовым вычислением остатка прошёл отдельную GPU-проверку. Полная картинка с исправлением проверена на 6 входах: вода без краски оставляет ровно нулевой цвет, количество слабого цвета восстановлено. Исправленный PACK совпал побайтно на Samsung и Intel в 3 проверенных сценах. На Intel та же ошибка остатка не воспроизвелась; точный слой сбоя на Samsung пока не установлен.</td></tr>
<tr><td>Объединение GPU-шагов и уменьшение повторных вычислений не дали ожидаемого ускорения.</td><td>Картинки совпали полностью, но серия перемешанных замеров не показала устойчивого выигрыша. Эти варианты не объявлены улучшением скорости.</td></tr>
<tr><td>Рядом с полностью непрозрачным сухим пикселем модель замораживает и часть соседней мокрой краски.</td><td>Найдено, пока не исправлено. Сухой пиксель сохранён точно, но консервативное ограничение ёмкости крупной ячейки влияет на соседние мокрые пиксели.</td></tr>
<tr><td>По одному расширению внешнего контура нельзя оценить, работает ли алгоритм.</td><td>Проверено исходным алгоритмом на 13 тех же мазках: у широкой волны средний выход за исходный след около 0.08px. Это не измеряет движение внутри заливки. Ранняя интерпретация небольших значений как провала заменена отдельными проверками смешения и формы потока.</td></tr>
<tr><td>В последнем эксперименте связка мелкой бумаги могла незаметно выключить вихревой перенос.</td><td>Исправлено до запуска этого варианта на GPU. Проверка теперь хеширует фактически переданный в GPU код и отдельно сравнивает включённые и выключенные вихри. Прежние проверенные сборки работали правильно: восстановленный вариант совпал с ними побайтно.</td></tr>
<tr><td>Некоторые параметры эксперимента можно было указать, хотя модель их игнорировала.</td><td>Для 30 семейств неизвестные и неподдерживаемые параметры теперь отклоняются до выделения GPU. Это защищает сравнение от ложных вариантов с одинаковым расчётом.</td></tr>
<tr><td>Укрупнение шага ускоряет расчёт, но может менять течение, смешение и давать ступеньки внутри заливки.</td><td>Ускорение подтверждено на контрольных сценах, технические проверки пройдены. Это отдельная приближённая модель. Художественный компромисс ещё оценивается; она не объявлена заменой исходнику.</td></tr>
<tr><td>После смены входа GPU мог бы оставить воду или пигмент предыдущего расчёта.</td><td>Отдельная проверка двух ускоренных моделей пройдена: мазок → чистая вода → мазок → сухой непрозрачный материал → вода → мазок. Каждый результат и диагностические суммы совпали со свежим расчётом; чистая вода дала ровно нулевой цвет. Дополнительные серии из 264 запусков пяти текущих кандидатов на 12 специально сгенерированных сложных входах также прошла: свежий расчёт, смена входа, возврат к прежнему входу, слабый цвет, почти непрозрачные точки, вода и сухой материал. Для мелкого переноса отдельно сверены все четыре суммы до и после в 24 контрольных расчётах. Это ограниченная воспроизводимая серия, а не перебор всех возможных рисунков.</td></tr>
<tr><td>Около почти непрозрачного сухого пикселя итоговая картинка теряет небольшую часть материала при восстановлении и переводе в байты.</td><td>Частично исправлено. В стрессовой серии прежнего восстановления отклонение суммы alpha доходило примерно до−0.75%, цветовых каналов до−0.90%. Внутренний расчёт сохраняет все 4 канала точно; это не оправдывает потерю в конечной картинке. Сами сухие точки сохранились: проверены 5 уровней прозрачности во всех 64 положениях внутри ячейки на двух моделях. Непрозрачные точки совпали полностью. В новом восстановлении, учитывающем свободную ёмкость пикселя, на плотных контрольных мазках потеря alpha уменьшилась примерно с 0.7% до 0.013%; на листе 12 остаётся около 0.18%. На всех 13 выбранных мазках после исправлений худшее отклонение суммы alpha около −0.23%, одного слабого цветового канала около −1.48%. Это измерения конечного 8-битного носителя; внутренние целочисленные суммы сохраняются. Полное сохранение конечной картинки пока не достигнуто.</td></tr></tbody></table>
<h2>Как повторить проверенные ситуации</h2><ol>
<li>Сделать широкую лужу чистой воды и поставить маленькую синюю каплю в центре. Посмотреть, насколько далеко уходит краска.</li>
<li>Поставить синий и жёлтый следы в общей воде, сначала далеко, затем близко, без начального наложения. Проверить появление смеси между ними.</li>
<li>В модели с неподвижной мокрой областью отделить лужи вертикальной и диагональной сухой полосой. Проверить весь путь переноса, а не только цвет самой полосы.</li>
<li>Соединить две лужи узкой протокой и посмотреть, проходит ли краска через соединение.</li>
<li>Повторить каплю на плоской и фактурной бумаге. Оценить, влияет ли бумага на материал, а не просто добавляет шум.</li>
<li>Запустить чистую воду без пигмента; цвет появляться не должен. Запустить пигмент совсем без воды; исходник должен сохраниться.</li>
<li>Повторить настоящие записанные кистевые операции Mini и подать альтернативам захват тех же полей краски, воды и бумаги.</li>
<li>Проверить широкую волну и примеры из галереи. Смотреть на непрерывность заливки, внешний край, клетку и потерю цвета.</li>
<li>Провести узкий штрих через широкую заранее намоченную область. Сравнить ширину растекания внутри и снаружи неё.</li><li>Провести два непересекающихся цветных штриха в общей воде. Проверить, встречаются ли цвета и появляется ли смесь между ними.</li></ol><p>Сухая полоса здесь проверяет контракт моделей с неподвижной мокрой областью. Сухая бумага не является физической стенкой: для модели, которая сама смачивает бумагу, нужны другие проверки воды и пигмента.</p>
<h2>Что ещё не готово и не проверено</h2><p>Не выбран художественно лучший алгоритм. На Samsung проверено движение воды. На Samsung и Intel UHD сравнили одинаковые байты: у ранних float-формул были различия до одного уровня цвета. Ранняя серия целочисленных моделей совпала побайтно в 11 проверках. Дополнительная серия из 12 проверок новых укрупнённых шагов и компактной мелкой бумаги также совпала полностью между Samsung Adreno и Intel UHD: все каналы, суммы материала и код фактического GPU-расчёта. Это сравнение одинаковых захваченных входных полей, а не проверка формирования мазка на разных устройствах. Отдельная проверка исходного алгоритма на 13 мазках подтвердила прежние входные данные побайтно. Ещё шесть сравнений текущих кандидатов между Samsung и Intel также совпали побайтно: одинаковы все пиксели, поле переноса и диагностические суммы; GPU-подготовка начальных буферов проверена на обоих устройствах. Полного покрытия всех моделей и устройств пока нет. Surface недоступен по SSH; iPad и Vega в этой серии не проверялись. Новые варианты не встроены в Grafetto: совместное рисование, undo/redo, большие листы A2 и полная задержка пера для них не проверялись.</p>
<h2>Фактура и память</h2><p>Добавлены три более мягких уровня бумажной фактуры. Все сохраняют количество материала внутри стадии мелкого переноса; художественное качество пока оценивается глазами. В отдельной точной оптимизации служебный GPU-буфер уменьшен на 12 MiB при 1024². Следующая упаковка цветовых носителей убрала ещё 24 MiB рабочих и 8 MiB диагностических буферов; итого 44 MiB с учётом диагностики. Полные картинки совпали с контролем. Это размер выделяемых GPU-буферов, а не измерение памяти всего браузера. У первой упаковки общий выигрыш времени составил 0–6%; главным результатом считаем экономию памяти.</p><h2>Ускорение исходного Mini</h2><p>Повторное вычисление фронтового шума вынесено в кэш размером 4 MiB. На шести фиксированных мазках полные поля пигмента, воды, покрытия и конечная PNG совпали побайтно. Это результат этих проверок: из-за 16-битного хранения кэша универсальная точность для любого ввода не доказана.</p><p>Чередование контрольного и нового вариантов после пятисекундной паузы подтвердило ускорение примерно на 14–15%. По четыре замера на вариант: волна 218→186 мс, два цвета 286→243 мс, лист 12 — 211→183 мс. Заполнение кэша входит во время; первые холодные запуски сохранены отдельно. Это прежний художественный алгоритм, а не замена на упрощённую модель. В Grafetto изменение ещё не встроено.</p><h2>Ускорения новых моделей</h2><p>Для новой целочисленной WebGPU-модели подготовка входных полей переписана без изменения результата. В перемешанной серии на трёх мазках облегчённая версия стала считать за 56–57 мс вместо 79–84 мс; вариант с мелкой бумагой — за 149–157 мс вместо 166–176 мс. Сравнивались полные байты результата, они совпали. Это ускорение подготовки и загрузки; GPU-формула не изменилась.</p><p>После пяти секунд без расчёта лёгкая версия заняла 135–148 мс, версия с мелкой бумагой 153–185 мс. Поэтому 56 мс не обещаем как обычный отклик после паузы. Частоты GPU не измерялись; причину изменения скорости пока не считаем доказанной.</p><p>Ещё один точный кандидат переносит подготовку начального материала на GPU. Конечные пиксели совпали с CPU-подготовкой на всех 13 мазках. Для шести входов дополнительно совпали сами начальные GPU-буферы и диагностические суммы. Непрерывная серия дала 41–58 мс полной готовности, отдельные замеры после паузы — 64–82 мс. Чередование двух вариантов после пятисекундных пауз подтвердило ускорение на 19–22% при одинаковых пикселях: 76→62 мс на волне, 101→78 мс на двух цветах, 95→76 мс на листе 12. Это три проверенные сцены, а не гарантия для любого мазка. На GPU подготовка занимала примерно 2.6–3.1 мс после первого запуска.</p><p>Улучшенная реконструкция цвета также объединена с GPU-подготовкой: восемь пар контрольных расчётов дали одинаковые пиксели. В серии с чередованием после пауз облегчённый вариант ускорился с 80 до 61 мс на волне и со 109 до 80 мс на двух цветах. Вариант с мелкой бумагой — с 83 до 76 мс и со 113 до 92 мс. Это точная оптимизация новых кандидатов, не сохранение художественного результата прежнего Mini.</p><h2>Новые варианты и отрицательные результаты</h2><p>Серия с чередованием порядка закончена: по 4 замера после 5 с паузы на вариант и сцену. Крупный шаг без мелкой бумаги:65/98/90 мс вместо 124/163/134 мс на волне, двух цветах и листе 12. С одинаковыми 4 шагами мелкой бумаги:87/109/113 мс вместо 127/156/147 мс. Это изменение картинки, а не точная оптимизация. Разброс сохранён: например, два цвета в быстрой облегчённой версии 85–130 мс. Оба быстрых варианта дополнительно прошли все 13 выбранных мазков; художественного победителя пока нет.</p><p>Уменьшение частоты смешения сохраняет материал, но заметно ослабляет соединение цветов. Ограниченная реконструкция дала только небольшое изменение размытия. Местное накопление у кромки на части сцен вообще не меняло картинку. Попытка вернуть подробности исходного мазка строго внутри каждой крупной ячейки сохраняла суммы, но создавала клетку и белые дырки — отклонена ещё до GPU. Эти опыты сохранены как отрицательные результаты. Вычисление каждой пары ячеек один раз также сохранило все пиксели, но в отдельной серии расчёт после загрузки данных стал медленнее примерно на 4–7 мс; этот вариант не принят как ускорение. Поиск четырёх точных вариантов текущего GPU-ядра тоже дал одинаковые пиксели и одинаковое полное внутреннее состояние на двух сценах, но преимущества скорости самого расчёта пока не показал.</p><p>Отдельные GPU timestamp-запросы показали 17–18 мс для основного GPU-прохода: растекание и сборка выходных пикселей и ещё 11–13 мс для 4 мелких шагов. Начальный запуск мелкой стадии занимал 21–24 мс. Эти замеры с профилированием выделены отдельно: полная готовность также включает подготовку и загрузку, а GPU-время не равно задержке пера.</p><h2>Другой способ переноса: пока только CPU</h2><p>Проверен перенос плотностей без усреднения исходного пигмента по крупным ячейкам. Без искусственного ограничения ёмкости плотный след перемещается на 56 пикселей с точным сохранением четырёх сумм. Первая схема с ограничением отклонена: плотный материал почти останавливался. Добавлены два способа смешения; у одного округление создаёт слабое зерно на границе воды, у другого слабые градиенты замирают. Смешение раздельных пятен пока недостаточное. Это численные прототипы на CPU, а не готовый акварельный алгоритм: GPU-скорость и художественное качество не подтверждены.</p><h2>Как читать время</h2><p>Замеры сделаны на настоящем Samsung Tab S7+. Показано время подготовки, загрузки и расчёта до принятой точки готовности. Для WebGL это зависимое чтение одного пикселя, для WebGPU — ожидание очереди; это разные границы. Полное чтение, хеши и PNG первоначально вынесены за интервал. Дополнительно измерено полное чтение: обычное RGBA чтение добавляло примерно 10–16 мс. У вариантов с мелкой бумагой диагностическое чтение ещё 16 MiB и подсчёт сумм занимали около 30–45 мс; это проверочный код, а не предлагаемый путь показа рисунка. У тестов с пустым центральным пикселем большого скрытого остатка не обнаружено; универсальной гарантией это не является. Эти числа не являются чистым GPU-временем или полным откликом Grafetto.</p><p>Суммы цветовых носителей — диагностический показатель, а не физическая масса пигмента. Перевод исходной модели в общий формат также приближённый: на листе 7 в семи пикселях один цветовой канал на единицу выше alpha. Эти байты сохранены без исправления; исходнику не приписываем контракт новых ограниченных носителей. Совпадение повторов на одном Samsung не доказывает одинаковый результат на разных устройствах. Указанные отдельно 12 межустройственных проверок относятся только к их фиксированным входам и параметрам.</p>
<p><a href="eddy/index.html">Все 12 сочетаний формы вихрей</a> · <a href="index.html">Контрольные картинки</a> · <a href="index.html">Все алгоритмы и оптимизации</a></p>'''
if a.worker_queue:
    snapshot=queue_snapshot(a.worker_queue,a.references)
    if a.progress_json:a.progress_json.write_text(json.dumps(snapshot,ensure_ascii=False,indent=2)+'\n')
    status=f"""<section id="fixed-matrix-progress"><h2>Пересчёт всей матрицы — текущий снимок</h2>
<p>Снимок UTC: {html.escape(snapshot['snapshotUTC'])}. Очередь начата: {html.escape(str(snapshot['startedAt']))}.</p>
<p>Запущена очередь {snapshot['plannedWorker']} worker-клеток. Ещё {snapshot['excludedCapillary']} capillary-клеток исключены до отдельного исправления и проверки. Это не полный готовый fixed-набор.</p>
<p>Получено уникальных строк PASS с совпавшим независимым raw-аудитом: {snapshot['auditedUniqueRows']}/{snapshot['plannedWorker']}. Из них в завершённых отчётах со стабильным source и закрытым context: {snapshot['closedBatchRows']}.</p>
<p>Ошибки строк или batch: {snapshot['failedRowsOrBatches']}; строки без полного raw-доказательства: {snapshot['unverifiedRows']}; повторные строки: {snapshot['duplicateRows']}; обновляемые/нечитаемые отчёты: {snapshot['updatingReportFiles']}.</p>
<p>Исходные CPU-reference: {snapshot['referencesVerified']}/30 проверены. Native component-isolated расчёты ещё ожидаются. Старые660 изображений пока остаются историческими; они не становятся результатами новой политики.</p></section>"""
    body=body.replace('<h2>Неподвижная исходная лужа',status+'<h2>Неподвижная исходная лужа',1)
style='body{font:17px/1.6 system-ui;color:#252723;background:#f2f1ed;margin:0}main{max-width:900px;margin:auto;padding:20px}h1{line-height:1.2}h2{font-size:22px;margin-top:32px}table{border-collapse:collapse;width:100%;font-size:15px}td,th{padding:12px;border:1px solid #ccc;vertical-align:top;text-align:left}a{color:#3e664c}@media(max-width:500px){main{padding:14px}td,th{padding:8px;font-size:14px}}'
a.output.write_text('<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Исследование растекания</title><style>'+style+'</style><main>'+body+'</main></html>')
